import { readFileSync, writeFileSync, unlinkSync } from 'node:fs';

writeFileSync(
  'src/lib/comparison-memo.ts',
  `export const comparisonMemoStorageKey = "kuraberu:comparison-memo:v1";\nexport const comparisonMemoLimit = 50;\n\nexport interface ComparisonMemoState {\n  version: 1;\n  ids: readonly string[];\n}\n\nexport function sanitizeComparisonMemo(\n  raw: string | null,\n  knownIds: readonly string[],\n): ComparisonMemoState {\n  if (!raw) return { version: 1, ids: [] };\n  try {\n    const parsed: unknown = JSON.parse(raw);\n    if (!parsed || typeof parsed !== "object") return { version: 1, ids: [] };\n    const candidate = parsed as { version?: unknown; ids?: unknown };\n    if (candidate.version !== 1 || !Array.isArray(candidate.ids)) {\n      return { version: 1, ids: [] };\n    }\n    const allowed = new Set(knownIds);\n    const ids: string[] = [];\n    for (const value of candidate.ids) {\n      if (typeof value !== "string" || !allowed.has(value) || ids.includes(value)) continue;\n      ids.push(value);\n      if (ids.length >= comparisonMemoLimit) break;\n    }\n    return { version: 1, ids };\n  } catch {\n    return { version: 1, ids: [] };\n  }\n}\n\nexport function encodeComparisonMemo(ids: readonly string[]): string {\n  return JSON.stringify({ version: 1, ids: [...ids].slice(0, comparisonMemoLimit) });\n}\n\nexport function toggleComparisonMemo(\n  state: ComparisonMemoState,\n  articleId: string,\n): { state: ComparisonMemoState; added: boolean; atLimit: boolean } {\n  if (state.ids.includes(articleId)) {\n    return {\n      state: { version: 1, ids: state.ids.filter((id) => id !== articleId) },\n      added: false,\n      atLimit: false,\n    };\n  }\n  if (state.ids.length >= comparisonMemoLimit) {\n    return { state, added: false, atLimit: true };\n  }\n  return {\n    state: { version: 1, ids: [...state.ids, articleId] },\n    added: true,\n    atLimit: false,\n  };\n}\n`,
);

writeFileSync(
  'src/components/ComparisonMemoButton.astro',
  `---\ninterface Props {\n  articleId: string;\n}\nconst { articleId } = Astro.props;\n---\n<div class="memo-control" data-memo-control data-article-id={articleId}>\n  <button type="button" class="secondary-button memo-toggle" aria-pressed="false" data-memo-toggle>比較メモに保存</button>\n  <span class="meta" role="status" aria-live="polite" data-memo-status></span>\n</div>\n\n<script>\n  import { comparisonMemoStorageKey, encodeComparisonMemo, sanitizeComparisonMemo, toggleComparisonMemo } from '../lib/comparison-memo';\n  import { articleMetadata } from '../content/articles';\n\n  const knownIds = articleMetadata.map((article) => article.id);\n  document.querySelectorAll('[data-memo-control]').forEach((node) => {\n    if (!(node instanceof HTMLElement) || node.dataset.memoBound === 'true') return;\n    node.dataset.memoBound = 'true';\n    const articleId = node.dataset.articleId;\n    const button = node.querySelector('[data-memo-toggle]');\n    const status = node.querySelector('[data-memo-status]');\n    if (!articleId || !(button instanceof HTMLButtonElement)) return;\n\n    const render = (ids) => {\n      const saved = ids.includes(articleId);\n      button.setAttribute('aria-pressed', saved ? 'true' : 'false');\n      button.textContent = saved ? '比較メモから外す' : '比較メモに保存';\n    };\n\n    let state;\n    try {\n      state = sanitizeComparisonMemo(localStorage.getItem(comparisonMemoStorageKey), knownIds);\n      localStorage.setItem(comparisonMemoStorageKey, encodeComparisonMemo(state.ids));\n      render(state.ids);\n    } catch {\n      button.disabled = true;\n      if (status) status.textContent = 'このブラウザでは比較メモを利用できません';\n      return;\n    }\n\n    button.addEventListener('click', () => {\n      const result = toggleComparisonMemo(state, articleId);\n      if (result.atLimit) {\n        if (status) status.textContent = '保存上限の50件に達しています';\n        return;\n      }\n      try {\n        localStorage.setItem(comparisonMemoStorageKey, encodeComparisonMemo(result.state.ids));\n        state = result.state;\n        render(state.ids);\n        if (status) status.textContent = result.added ? '比較メモに保存しました' : '比較メモから外しました';\n        window.dispatchEvent(new CustomEvent('comparison-memo-change', { detail: state.ids }));\n      } catch {\n        if (status) status.textContent = '保存できませんでした。ブラウザの保存設定を確認してください';\n      }\n    });\n  });\n</script>\n`,
);

writeFileSync(
  'src/pages/memo.astro',
  `---\nimport BaseLayout from '../layouts/BaseLayout.astro';\nimport { articleMetadata } from '../content/articles';\n---\n<BaseLayout title="比較メモ｜くらべる商品メモ" description="端末内に保存した比較記事を確認するページ">\n  <section class="section wrap article-index" data-memo-page>\n    <p class="eyebrow">Local comparison memo</p>\n    <h1>比較メモ</h1>\n    <p class="lead">保存状態はこのブラウザの端末内だけに保存されます。価格・在庫など変化する情報は保存せず、記事の最新版へ移動します。</p>\n    <p class="meta" role="status" aria-live="polite" data-memo-page-status>保存状態を確認しています</p>\n    <div class="article-list" data-memo-list>\n      {articleMetadata.map((article) => (\n        <article class="card article-list-card" data-memo-item data-article-id={article.id}>\n          <span class="tag">{article.category}</span>\n          <h2><a href={article.path}>{article.headline}</a></h2>\n          <p>{article.summary}</p>\n          <p class="meta">商品情報確認日 {article.productInfoCheckedAt ?? '未記録'}</p>\n          <a class="cta" href={article.path}>記事を確認する →</a>\n          <button type="button" class="text-button" data-memo-remove>比較メモから外す</button>\n        </article>\n      ))}\n    </div>\n    <div class="card discovery-empty" hidden data-memo-empty>\n      <h2>保存した記事はありません</h2>\n      <p><a href="/articles/">比較記事一覧から記事を探す →</a></p>\n    </div>\n    <noscript><p class="notice">比較メモの保存状態を表示するにはJavaScriptが必要です。下の記事リンクから通常どおり閲覧できます。</p></noscript>\n  </section>\n\n  <script>\n    import { comparisonMemoStorageKey, encodeComparisonMemo, sanitizeComparisonMemo } from '../lib/comparison-memo';\n    import { articleMetadata } from '../content/articles';\n\n    const root = document.querySelector('[data-memo-page]');\n    if (root instanceof HTMLElement) {\n      const knownIds = articleMetadata.map((article) => article.id);\n      const status = root.querySelector('[data-memo-page-status]');\n      const empty = root.querySelector('[data-memo-empty]');\n      const items = [...root.querySelectorAll('[data-memo-item]')];\n      let ids = [];\n      let storageAvailable = true;\n      try {\n        ids = [...sanitizeComparisonMemo(localStorage.getItem(comparisonMemoStorageKey), knownIds).ids];\n        localStorage.setItem(comparisonMemoStorageKey, encodeComparisonMemo(ids));\n      } catch {\n        storageAvailable = false;\n      }\n      const render = () => {\n        let visible = 0;\n        items.forEach((item) => {\n          if (!(item instanceof HTMLElement)) return;\n          const saved = ids.includes(item.dataset.articleId || '');\n          item.hidden = storageAvailable && !saved;\n          item.querySelector('[data-memo-remove]')?.toggleAttribute('disabled', !storageAvailable);\n          if (saved) visible += 1;\n        });\n        if (empty instanceof HTMLElement) empty.hidden = !storageAvailable || visible !== 0;\n        if (status) status.textContent = storageAvailable ? visible + '件保存されています' : 'このブラウザでは比較メモを利用できません。記事リンクは通常どおり利用できます';\n      };\n      root.querySelectorAll('[data-memo-remove]').forEach((button) => button.addEventListener('click', () => {\n        const item = button.closest('[data-memo-item]');\n        if (!(item instanceof HTMLElement)) return;\n        ids = ids.filter((id) => id !== item.dataset.articleId);\n        try {\n          localStorage.setItem(comparisonMemoStorageKey, encodeComparisonMemo(ids));\n          render();\n        } catch {\n          storageAvailable = false;\n          render();\n        }\n      }));\n      render();\n    }\n  </script>\n</BaseLayout>\n`,
);

let layout = readFileSync('src/layouts/BaseLayout.astro', 'utf8');
layout = layout.replace(
  '          <a href="/articles/">比較記事</a>\n          <a href="/about/">運営者情報</a>',
  '          <a href="/articles/">比較記事</a>\n          <a href="/memo/">比較メモ</a>\n          <a href="/about/">運営者情報</a>',
);
writeFileSync('src/layouts/BaseLayout.astro', layout);

let article = readFileSync('src/pages/articles/pampers-newborn/index.astro', 'utf8');
article = article.replace(
  "import DifferenceList from '../../../components/DifferenceList.astro';\n",
  "import DifferenceList from '../../../components/DifferenceList.astro';\nimport ComparisonMemoButton from '../../../components/ComparisonMemoButton.astro';\n",
);
article = article.replace(
  '    <h1>{articleMetadata.headline}</h1>\n',
  '    <h1>{articleMetadata.headline}</h1>\n    <ComparisonMemoButton articleId={articleMetadata.id} />\n',
);
writeFileSync('src/pages/articles/pampers-newborn/index.astro', article);

let css = readFileSync('src/styles/global.css', 'utf8');
css += `\n.memo-control { display: flex; align-items: center; gap: 0.75rem; flex-wrap: wrap; margin: 0.75rem 0 1.25rem; }\n.memo-toggle[aria-pressed="true"] { background: var(--ink); color: var(--paper); }\n.text-button { margin-top: 1rem; border: 0; background: transparent; color: var(--ink); padding: 0.5rem 0; font: inherit; font-weight: 800; text-decoration: underline; text-underline-offset: 4px; cursor: pointer; }\n.text-button:disabled { color: var(--muted); cursor: not-allowed; }\n`;
writeFileSync('src/styles/global.css', css);

writeFileSync(
  'tests/comparison-memo.test.ts',
  `import { readFileSync } from "node:fs";\nimport { describe, expect, it } from "vitest";\nimport { articleMetadata } from "../src/content/articles";\nimport { comparisonMemoLimit, encodeComparisonMemo, sanitizeComparisonMemo, toggleComparisonMemo } from "../src/lib/comparison-memo";\n\ndescribe("comparison memo", () => {\n  const knownIds = articleMetadata.map((article) => article.id);\n  it("recovers corrupt, obsolete and duplicate data safely", () => {\n    expect(sanitizeComparisonMemo("not-json", knownIds).ids).toEqual([]);\n    expect(sanitizeComparisonMemo(JSON.stringify({ version: 9, ids: knownIds }), knownIds).ids).toEqual([]);\n    expect(sanitizeComparisonMemo(JSON.stringify({ version: 1, ids: [knownIds[0], knownIds[0], "removed"] }), knownIds).ids).toEqual([knownIds[0]]);\n  });\n  it("toggles without duplicates and enforces the limit", () => {\n    const added = toggleComparisonMemo({ version: 1, ids: [] }, knownIds[0]);\n    expect(added.added).toBe(true);\n    expect(toggleComparisonMemo(added.state, knownIds[0]).state.ids).toEqual([]);\n    const full = { version: 1 as const, ids: Array.from({ length: comparisonMemoLimit }, (_, index) => "id-" + index) };\n    expect(toggleComparisonMemo(full, "another").atLimit).toBe(true);\n  });\n  it("stores only version and article ids", () => {\n    expect(encodeComparisonMemo([knownIds[0]])).toBe(JSON.stringify({ version: 1, ids: [knownIds[0]] }));\n  });\n  it("renders memo controls while keeping article links without JavaScript", () => {\n    const articleHtml = readFileSync("dist/articles/pampers-newborn/index.html", "utf8");\n    const memoHtml = readFileSync("dist/memo/index.html", "utf8");\n    expect(articleHtml).toContain("比較メモに保存");\n    expect(memoHtml).toContain("このブラウザの端末内だけ");\n    expect(memoHtml).toContain(articleMetadata[0].path);\n    expect(memoHtml).toContain("<noscript>");\n  });\n});\n`,
);

unlinkSync('.github/agent-apply-comparison-memo.mjs');
